        public IReadOnlyDictionary<string, double> GetMetrics() => _metrics;

        public IReadOnlyList<double[]> GetHistory(int lastN = 100)
            => _history.TakeLast(lastN).ToList();

        public async Task SaveStateAsync(string path, CancellationToken ct = default)
        {
            var state = new { Step = _step, Metrics = _metrics, Config = _config };
            var json = JsonSerializer.Serialize(state, new JsonSerializerOptions { WriteIndented = true });
            await File.WriteAllTextAsync(path, json, ct).ConfigureAwait(false);
        }

        public async Task LoadStateAsync(string path, CancellationToken ct = default)
        {
            var json = await File.ReadAllTextAsync(path, ct).ConfigureAwait(false);
            using var doc = JsonDocument.Parse(json);
            _step = doc.RootElement.GetProperty("Step").GetInt64();
        }

        public void Reset()
        {
            Interlocked.Exchange(ref _step, 0);
            _metrics.Clear();
            _history.Clear();
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _cts.Cancel();
            _cts.Dispose();
            _semaphore.Dispose();
            GC.SuppressFinalize(this);
        }

        public override string ToString()
            => $"maia_federated_learningComponent2(Step={_step}, Metrics={_metrics.Count}, NodeId={_config.NodeId})";
    }

